package net.y4k.progression.application;

import java.util.*;
import net.y4k.progression.domain.SpawnGrid.Point;

/** One probe per step; unavailable terrain is skipped, never generated by the search. */
public final class SpawnSearch {
    public interface Probe { Optional<Integer> safeY(Point point); }
    public record Destination(Point point, int y) {}
    private final Iterator<Point> points;
    private final Set<String> reserved;
    private final Probe probe;
    private int remaining;
    private boolean exhausted;
    public SpawnSearch(List<Point> points, Set<String> reserved, Probe probe, int maxAttempts) {
        if (maxAttempts < 1 || maxAttempts > 1000) throw new IllegalArgumentException("Invalid attempt limit");
        this.points = points.iterator(); this.reserved = reserved; this.probe = probe; remaining = maxAttempts;
    }
    public Optional<Destination> step() {
        if (exhausted) return Optional.empty();
        while (points.hasNext() && remaining-- > 0) {
            var point = points.next();
            if (reserved.contains(point.key())) continue;
            var y = probe.safeY(point);
            if (y.isPresent()) return Optional.of(new Destination(point, y.get()));
            // A failed probe consumes this step's budget, not the whole search in one tick.
            if (!points.hasNext() || remaining <= 0) exhausted = true;
            return Optional.empty();
        }
        exhausted = true; return Optional.empty();
    }
    public boolean exhausted() { return exhausted; }
}
